#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> ans;
    ans.push_back(n);

    for (int i = 2; i <= n;) {
        if (ans.back() % i != 0) {
            ++i;
            continue;
        }

        int divided = ans.back() / i;
        ans.push_back(divided);

        if (divided == 1) break;
    }

    for (int value : ans)
        cout << value << ' ';

    return 0;
}

